import{_ as o,c as l,a2 as p,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千二百零二章 第二不放逸品 增支部1集98经到139经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1202第一千二百零二章 第二不放逸品 增支部1集98经到139经.md","filePath":"meditation/巴利文大藏经/1202第一千二百零二章 第二不放逸品 增支部1集98经到139经.md"}'),a={name:"meditation/巴利文大藏经/1202第一千二百零二章 第二不放逸品 增支部1集98经到139经.md"};function u(r,t,q,e,s,_){return i(),l("div",null,t[0]||(t[0]=[p('<h1 id="第一千二百零二章-第二不放逸品-增支部1集98经到139经" tabindex="-1">第一千二百零二章 第二不放逸品 增支部1集98经到139经 <a class="header-anchor" href="#第一千二百零二章-第二不放逸品-增支部1集98经到139经" aria-label="Permalink to &quot;第一千二百零二章 第二不放逸品 增支部1集98经到139经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集98经到139经</p><p>98经</p><ol start="98"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像放逸这样导致如此大的不利。诸比丘,放逸会导致巨大的不利。&quot; 第一。</li></ol><p>99经</p><ol start="99"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像不放逸这样导致如此大的利益。诸比丘,不放逸会导致巨大的利益。&quot; 第二。</li></ol><p>100经</p><ol start="100"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像懒惰这样导致如此大的不利。诸比丘,懒惰会导致巨大的不利。&quot; 第三。</li></ol><p>101经</p><ol start="101"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像精进这样导致如此大的利益。诸比丘,精进会导致巨大的利益。&quot; 第四。</li></ol><p>102-109经</p><p>102-109. &quot;诸比丘,就内在因素而言,我不见有任何一法,会像贪欲...少欲...不知足...知足...不如理作意...如理作意...不正知...正知这样导致如此大的不利或利益。&quot; 第十二。</p><p>110经</p><ol start="110"><li>&quot;诸比丘,就外在因素而言,我不见有任何一法,会像恶友这样导致如此大的不利。诸比丘,恶友会导致巨大的不利。&quot; 第十三。</li></ol><p>111经</p><ol start="111"><li>&quot;诸比丘,就外在因素而言,我不见有任何一法,会像善友这样导致如此大的利益。诸比丘,善友会导致巨大的利益。&quot; 第十四。</li></ol><p>112经</p><ol start="112"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像修习不善法、不修习善法这样导致如此大的不利。诸比丘,修习不善法、不修习善法会导致巨大的不利。&quot; 第十五。</li></ol><p>113经</p><ol start="113"><li>&quot;诸比丘,就内在因素而言,我不见有任何一法,会像修习善法、不修习不善法这样导致如此大的利益。诸比丘,修习善法、不修习不善法会导致巨大的利益。&quot; 第十六。</li></ol><p>114经</p><ol start="114"><li>&quot;诸比丘,我不见有任何一法,会像放逸这样导致正法的衰退、消失。诸比丘,放逸会导致正法的衰退、消失。&quot; 第十七。</li></ol><p>115经</p><ol start="115"><li>&quot;诸比丘,我不见有任何一法,会像不放逸这样导致正法的安住、不衰退、不消失。诸比丘,不放逸会导致正法的安住、不衰退、不消失。&quot; 第十八。</li></ol><p>116经</p><ol start="116"><li>&quot;诸比丘,我不见有任何一法,会像懒惰这样导致正法的衰退、消失。诸比丘,懒惰会导致正法的衰退、消失。&quot; 第十九。</li></ol><p>117经</p><ol start="117"><li>&quot;诸比丘,我不见有任何一法,会像精进这样导致正法的安住、不衰退、不消失。诸比丘,精进会导致正法的安住、不衰退、不消失。&quot; 第二十。</li></ol><p>118-128经</p><p>118-128. &quot;诸比丘,我不见有任何一法,会像贪欲...少欲...不知足...知足...不如理作意...如理作意...不正知...正知...恶友...善友...修习不善法、不修习善法这样导致正法的衰退、消失。诸比丘,修习不善法、不修习善法会导致正法的衰退、消失。&quot; 第三十一。</p><p>129经</p><ol start="129"><li>&quot;诸比丘,我不见有任何一法,会像修习善法、不修习不善法这样导致正法的安住、不衰退、不消失。诸比丘,修习善法、不修习不善法会导致正法的安住、不衰退、不消失。&quot; 四种组合已完成。第三十二。</li></ol><p>130经</p><ol start="130"><li>&quot;诸比丘,那些将非法说成是法的比丘,他们是为了多数人的不利而行,为了多数人的不安乐,为了众生的损害、不利、痛苦而行。诸比丘,那些比丘造作了大量的罪业,他们使这正法消失。&quot; 第三十三。</li></ol><p>131经</p><ol start="131"><li>&quot;诸比丘,那些将法说成是非法的比丘,他们是为了多数人的不利而行,为了多数人的不安乐,为了众生的损害、不利、痛苦而行。诸比丘,那些比丘造作了大量的罪业,他们使这正法消失。&quot; 第三十四。</li></ol><p>132-139经</p><p>132-139. &quot;诸比丘,那些将非律说成是律的比丘...将律说成是非律的比丘...将如来未说、未讲的说成是如来所说、所讲的比丘...将如来所说、所讲的说成是如来未说、未讲的比丘...将如来未修习的说成是如来所修习的比丘...将如来所修习的说成是如来未修习的比丘...将如来未制定的说成是如来所制定的比丘...将如来所制定的说成是如来未制定的比丘,他们是为了多数人的不利而行,为了多数人的不安乐,为了众生的损害、不利、痛苦而行。诸比丘,那些比丘造作了大量的罪业,他们使这正法消失。&quot; 第四十二。</p><p>第二不放逸品第十品结束。</p>',40)]))}const c=o(a,[["render",u]]);export{d as __pageData,c as default};
